use mech_syntax::document::*;
fn drain(s: &mut DocumentStream, mut u: StreamUpdate) -> StreamUpdate { let mut n=0; while u.progress==StreamProgress::NeedsProcessing {u=s.advance(31);n+=1;if n>100000 {panic!("loop")}} u }
fn main(){for (prefix,suffix) in [("x := [","1]\n"),("x := [1,","2]\n")]{for preview in [false,true]{let source=format!("{prefix}{suffix}");let one=DocumentSession::new(&source,ParseConfig::default());println!("one source={source:?} clean={} stats={:?}",one.snapshot().is_strictly_clean(),one.snapshot().stats);let mut s=DocumentStream::with_limits(DocumentId(1),ParseConfig::default(),StreamLimits{max_source_bytes:1000,max_parser_work:100000});let u=s.append(prefix,31).unwrap();drain(&mut s,u);if preview {let p=s.preview();println!("preview clean={} work={:?}",p.snapshot.is_strictly_clean(),s.work());}let u=s.append(suffix,31).unwrap();let u=drain(&mut s,u);println!("append {preview}: {:?} {:?}",u.progress,s.work());let u=s.finish(31);let u=drain(&mut s,u);println!("final {preview}: {:?} {:?}",u.progress,s.work());}}}
